    handleChuzhi: function handleChuzhi(row) {
      var _this8 = this;
      if (row.warningType !== '台账监控异常') {
        this.gotoDetial(row);
      } else {
        var form = {
          ciId: row.deviceCid,
          ciEntityId: row.deviceId,
          needAction: true
        };
        devBookDetail(form).then(function (res) {
          if (!res.data.Return) {
            _this8.$alert('台账暂无详情数据');
            return;
          }
          var resData = res.data.Return;
          var bookDetailForm = {};
          for (var key in resData.attrEntityData) {
            var dataItem = resData.attrEntityData[key];
            bookDetailForm[dataItem.name] = dataItem.actualValueList[0];
          }
          getHardwarebasictree(row.deviceCid).then(function (ax) {
            _this8.cmdbParams = {
              ciId: row.deviceCid,
              devId: row.deviceId
            };
            _this8.editParams.ciName = ax.data.ciName;
            _this8.editParams.devDetail = bookDetailForm;
            _this8.editParams.devid = row.deviceId;
            _this8.editParams.ciId = row.deviceCid;
            _this8.editParams.uuid = row.deviceUuid;
            _this8.editParams.colName = 'frombaox'; //来自数据保险→设备异动告警

            _this8.showCMDBEdit = true;
            _this8.tzjkycRow = row;
          });
        });
      }
    },
    handleSee: function handleSee(row) {
      this.gotoDetial(row);
    },
    rowDbClcik: function rowDbClcik(row, column, event) {
      var _this9 = this;
      if (row.btnStatus != '0') {
        this.gotoDetial(row);
        this.$EventBus.$once('sbydgjList', function (arg) {
          _this9.getList();
        });
      }
    },
    gotoDetial: function gotoDetial(row) {
      this.lazyIds = [];
      if (row.hasChildren) {
        this.lazyIds = [];
        this.lazyIds.push(row.id);
      }
      this.$router.push({
        path: '/detailRoute',
        query: {
          componentName: 'shebeiyidongDetial',
          routerTitle: '台账异动告警详情',
          id: row.id,
          operationId: row.disposeOrder,
          hasChildren: row.hasChildren,
          warningType: row.warningType
        }
      });
    },
    showArrow: function showArrow(type) {
      if (type === 'CORP' || type === 'DEPT') {
        return true;
      }
      return false;
    },
    getTypeName: function getTypeName(type) {
      if (type === 'CORP') {
        return '单位';
      } else if (type === 'DEPT') {
        return '部门';
      } else if (type === 'TEAM') {
        return '班组';
      }
      return '未知';
    },
    getErpName: function getErpName(row) {
      if (row) {
        if (row.type === 'CORP') {
          // 公司
          return row.erpUnit;
        } else {
          // 部门 DEPT  班组 TEAM
          return this.getEIObj(row, 'erpObj');
        }
      }
      return null;
    },
    getEIObj: function getEIObj(row, type) {
      if (type === 'erpObj') {
        if (!this.isEmpty(row.erpUnit) && !this.isEmpty(row.erpDept)) {
          return row.erpUnit + '/' + row.erpDept;
        } else if (!this.isEmpty(row.erpUnit)) {
          return row.erpUnit;
        } else if (!this.isEmpty(row.erpDept)) {
          return row.erpDept;
        }
      } else if (type === 'i6000Obj') {
        if (!this.isEmpty(row.i6000Unit) && !this.isEmpty(row.i6000Dept)) {
          return row.i6000Unit + '/' + row.i6000Dept;
        } else if (!this.isEmpty(row.i6000Unit)) {
          return row.i6000Unit;
        } else if (!this.isEmpty(row.i6000Dept)) {
          return row.i6000Dept;
        }
      }
      return null;
    },
    getI6000Name: function getI6000Name(row) {
      if (row) {
        if (row.type === 'CORP') {
          // 公司
          return row.i6000Unit;
        } else {
          // 部门 DEPT  班组 TEAM
          return this.getEIObj(row, 'i6000Obj');
        }
      }
      return null;
    },
    // 获得设备回显
    getuseApplyUnit: function getuseApplyUnit(val) {
      this.queryParams.receiveUnit = val.id;
      this.queryParams.receiveUnitName = val.fullName;
      this.$forceUpdate();
    },
    getTagType: function getTagType(type) {
      if (type == '紧急') {
        return 'danger';
      } else if (type == '主要') {
        return 'warning';
      } else if (type == '次要') {
        return '';
      } else if (type == '提示') {
        return 'success';
      }
    },
    heightLighText: function heightLighText(row) {
      //warningDetail
      //gatherIp
      //gatherMac
      if (row.warningDetail) {
        var mgText = '';
        if (!this.isEmpty(row.gatherIp) && !this.isEmpty(row.gatherMac)) {
          mgText = "".concat(row.gatherIp, "|").concat(row.gatherMac);
        } else if (!this.isEmpty(row.gatherIp)) {
          mgText = "".concat(row.gatherIp);
        } else if (!this.isEmpty(row.gatherMac)) {
          mgText = "".concat(row.gatherMac);
        }
        var reg = new RegExp(mgText, 'gi');
        var newStr = row.warningDetail.replace(reg, function (matchedText) {
          return "<span style=\"color:#FAAD15;\">".concat(matchedText, "</span>");
        });
        return newStr;
      } else return row.warningDetail;
    },
    getConfirmStatusText: function getConfirmStatusText(status) {
      if (status == 0) {
        return '待确认';
      } else if (status == 1) {
        return '已确认';
      } else if (status == 2) {
        return '已忽略';
      }
      return null;
    },
    getConfirmStatusColor: function getConfirmStatusColor(status) {
      if (status == 0) {
        return '#FAAD15';
      } else if (status == 1) {
        return '#51C41B';
      } else if (status == 2) {
        return '#BFBFBF';
      }
      return null;
    },
    getDisposeStatusText: function getDisposeStatusText(status) {
      if (status == 0) {
        return '待处置';
      } else if (status == 1) {
        return '已处置';
      } else if (status == 2) {
        return '已忽略';
      }
      return null;
    },
    isEmpty: function isEmpty(value) {
      if (value == null || value === '') {
        return true;
      }
      return false;
    },
    dataPickerChange: function dataPickerChange(createTimes) {
      //时间段选择
      if (createTimes != null && createTimes.length > 0) {
        this.queryParams.warningBeginTime = createTimes[0];
        this.queryParams.warningEndTime = createTimes[1];
      } else {
        this.queryParams.warningBeginTime = null;
        this.queryParams.warningEndTime = null;
      }
    },
    getColumnType: function getColumnType(row, column) {
      if (row.btnStatus != '0') {
        column.type = 'selection';
      }
      return null;
    },
    getUnitName: function getUnitName(unitName) {
      if (unitName == null || unitName == 'null') {
        return null;
      }
      return unitName;
    }
  }
};
